-- functions
-- Factorio 2.0+ 中 global 已被移除，改用 storage。
-- 兼容已有存档（on_init 不会再触发），在各个入口处懒初始化。
local function ensure_storage()
    storage.portal_belts = storage.portal_belts or {}
    storage.players = storage.players or {}
    storage.next_portal_id = storage.next_portal_id or 1
end

-- 生成指向实体位置的可点击 [gps] 链接（2.0 支持第三段 surface 名，跨星球可跳转）
local function gps_link(entity)
    return "[gps=" .. math.floor(entity.position.x) .. "," .. math.floor(entity.position.y)
        .. "," .. entity.surface.name .. "]"
end

-- 取配对搭档的实体（未配对或搭档已失效时返回 nil）
local function get_partner_entity(portal)
    if not portal or not portal.paired_with then return nil end
    local partner = storage.portal_belts[portal.paired_with]
    if partner and partner.entity and partner.entity.valid then
        return partner.entity
    end
    return nil
end

-- 处理传送带移除的函数
function handle_portal_belt_removed(entity)
    if not entity or not is_portal_belt(entity) then return end
    ensure_storage()

    -- 查找并移除传送带
    local portal_id_to_remove = nil
    for id, portal in pairs(storage.portal_belts) do
        if portal.entity == entity then
            portal_id_to_remove = id
            break
        end
    end

    if portal_id_to_remove then
        -- 如果有配对，解除配对
        local paired_id = storage.portal_belts[portal_id_to_remove].paired_with
        if paired_id and storage.portal_belts[paired_id] then
            storage.portal_belts[paired_id].paired_with = nil
        end

        -- 移除传送带
        storage.portal_belts[portal_id_to_remove] = nil
    end
end

-- 检查实体是否为传送带
function is_portal_belt(entity)
    if not entity or not entity.valid then return false end

    -- 添加调试日志
    -- log("检查实体类型: " .. entity.name)

    local portal_belt_types = {
        "portal-underground-belt",
        "portal-fast-underground-belt",
        "portal-express-underground-belt",
        "portal-turbo-underground-belt"
    }

    for _, belt_type in pairs(portal_belt_types) do
        if entity.name == belt_type then
            -- log("找到传送门类型: " .. entity.name)
            return true
        end
    end

    return false
end

-- 处理实体移除
function handle_entity_removed(entity)
    if not entity or not entity.valid then return end
    ensure_storage()

    if is_portal_belt(entity) then
        -- 查找对应的传送带ID
        for id, portal in pairs(storage.portal_belts) do
            if portal.entity == entity then
                -- 如果有配对，解除配对
                if portal.paired_with and storage.portal_belts[portal.paired_with] then
                    storage.portal_belts[portal.paired_with].paired_with = nil
                end

                -- 直接移除传送带记录
                storage.portal_belts[id] = nil
                break
            end
        end
    end
end

-- 显示当前传送带的状态
-- 两态窗口：未配对 → 显示可选搭档列表；已配对 → 锁定态，仅显示预览与解锁按钮
function show_pairing_gui(player_index, portal_id)
    ensure_storage()
    local player = game.players[player_index]
    local portal = storage.portal_belts[portal_id]

    if not portal then return end
    local my_entity = portal.entity
    if not my_entity or not my_entity.valid then return end

    -- 关闭已存在的配对界面
    if player.gui.center.portal_pairing_frame then
        player.gui.center.portal_pairing_frame.destroy()
    end

    -- 创建配对界面
    local frame = player.gui.center.add({
        type = "frame",
        name = "portal_pairing_frame",
        caption = {"gui.portal-pairing-title"}
    })

    local main_flow = frame.add({type = "flow", name = "main_flow", direction = "vertical"})

    local partner_entity = get_partner_entity(portal)
    if partner_entity then
        -- 已配对（锁定态）：实时预览 + 搭档信息 + 解锁按钮
        -- 注意：camera 的 position 是 add() 的必填参数（surface_index/zoom 可选），创建后再赋值会直接报错
        local camera = main_flow.add({
            type = "camera",
            name = "portal_partner_camera",
            position = partner_entity.position,
            surface_index = partner_entity.surface.index,
            zoom = 0.5
        })
        camera.style.width = 280
        camera.style.height = 180

        local partner_flow = main_flow.add({type = "flow", name = "partner_flow", direction = "horizontal"})
        partner_flow.add({
            type = "label",
            caption = {"gui.portal-partner-label",
                partner_entity.surface.name .. " (" .. math.floor(partner_entity.position.x)
                    .. ", " .. math.floor(partner_entity.position.y) .. ") " .. gps_link(partner_entity)}
        })
        partner_flow.add({
            type = "button",
            name = "portal_show_on_map_button",
            caption = {"gui.portal-show-on-map"}
        })

        local unlock_flow = main_flow.add({type = "flow", name = "unlock_flow", direction = "horizontal"})
        unlock_flow.add({
            type = "button",
            name = "portal_unlock_button",
            caption = {"gui.portal-unlock"}
        })
    else
        -- 未配对：列出所有可选搭档（有效、未配对、形态与本带相反）
        main_flow.add({type = "label", caption = {"gui.portal-select-section"}})

        local my_type = my_entity.belt_to_ground_type
        local candidates = {}
        for id, p in pairs(storage.portal_belts) do
            local e = p.entity
            if id ~= portal_id and e and e.valid
               and not p.paired_with
               and e.belt_to_ground_type ~= my_type then
                candidates[#candidates + 1] = {id = id, entity = e, label = p.name}
            end
        end
        table.sort(candidates, function(a, b)
            local ea, eb = a.entity, b.entity
            if ea.surface.name ~= eb.surface.name then
                return ea.surface.name < eb.surface.name
            end
            if ea.position.x ~= eb.position.x then
                return ea.position.x < eb.position.x
            end
            return ea.position.y < eb.position.y
        end)

        if #candidates == 0 then
            main_flow.add({type = "label", caption = {"gui.portal-no-candidates"}})
        else
            for _, cand in ipairs(candidates) do
                local e = cand.entity
                local row = main_flow.add({
                    type = "flow",
                    name = "candidate_flow_" .. cand.id,
                    direction = "horizontal"
                })
                local text = (cand.label and (cand.label .. " · ") or "")
                    .. e.surface.name .. " (" .. math.floor(e.position.x) .. ", " .. math.floor(e.position.y) .. ")"
                row.add({type = "label", caption = text})
                row.add({
                    type = "label",
                    caption = (e.belt_to_ground_type == "input")
                        and {"gui.portal-direction-in"} or {"gui.portal-direction-out"}
                })
                row.add({
                    type = "button",
                    name = "portal_select_button",
                    caption = {"gui.portal-select"},
                    tags = {portal_id = cand.id}
                })
            end
        end
    end

    -- 备注输入框（纯标签，便于人识别；不再参与配对逻辑）
    local name_flow = main_flow.add({type = "flow", name = "name_flow", direction = "horizontal"})
    name_flow.add({type = "label", caption = {"gui.portal-name-label"}})
    local name_textfield = name_flow.add({
        type = "textfield",
        name = "portal_name_textfield",
        text = portal.name or ""
    })

    -- 确认 = 保存备注并关闭；取消 = 直接关闭
    local button_flow = main_flow.add({type = "flow", name = "button_flow", direction = "horizontal"})
    button_flow.add({
        type = "button",
        name = "portal_confirm_button",
        caption = {"gui.confirm"}
    })
    button_flow.add({
        type = "button",
        name = "portal_cancel_button",
        caption = {"gui.cancel"}
    })

    -- 存储当前正在配置的传送带ID
    storage.players[player_index] = storage.players[player_index] or {}
    storage.players[player_index].configuring_portal_id = portal_id
end

-- 配对两个传送带
function pair_portal_belts(portal_id1, portal_id2)
    ensure_storage()
    if not storage.portal_belts[portal_id1] or not storage.portal_belts[portal_id2] then
        return false
    end

    storage.portal_belts[portal_id1].paired_with = portal_id2
    storage.portal_belts[portal_id2].paired_with = portal_id1

    return true
end

-- 注册传送带
function register_portal_belt(entity, player_index)
    ensure_storage()
    local portal_id = storage.next_portal_id
    storage.next_portal_id = storage.next_portal_id + 1

    -- 进出口方向不在此保存：以实体实时的 belt_to_ground_type 为准（按 R 翻转）
    storage.portal_belts[portal_id] = {
        entity = entity,
        surface = entity.surface.name,
        position = {x = entity.position.x, y = entity.position.y},
        type = entity.name,
        name = nil, -- 通过GUI设置
        paired_with = nil
    }

    return portal_id
end

-- 物品检测和传送逻辑
function transfer_items(source_belt, target_belt)
    -- 地下传送带有两条传送线（左右各一），逐线配对传送
    for i = 1, 2 do
        local source_line = source_belt.get_transport_line(i)
        local target_line = target_belt.get_transport_line(i)

        if source_line and target_line and source_line.valid and target_line.valid
           and source_line.get_item_count() > 0 then

            -- 2.0 的 get_detailed_contents() 返回数组，每项的物品字段是 stack（LuaItemStack）
            local contents = source_line.get_detailed_contents()

            -- 先快照物品信息，避免边传送边遍历导致引用失效
            local specs = {}
            for _, detail in pairs(contents) do
                local stack = detail.stack
                if stack and stack.valid and stack.name and stack.count > 0 then
                    specs[#specs + 1] = {
                        name = stack.name,
                        quality = stack.quality and stack.quality.name or "normal",
                        count = stack.count
                    }
                end
            end

            -- 逐个把物品从源线搬到目标线后端，目标装不下就停
            for _, spec in pairs(specs) do
                local item = {name = spec.name, quality = spec.quality, count = 1}
                for _ = 1, spec.count do
                    if not target_line.can_insert_at_back() then break end
                    if target_line.insert_at_back(item) then
                        source_line.remove_item(item)
                    else
                        break
                    end
                end
            end
        end
    end
end

